import{_ as s,o as e,c as n,a0 as t}from"./chunks/framework.DqMqoJl9.js";const b=JSON.parse('{"title":"Date.parse()","description":"","frontmatter":{},"headers":[],"relativePath":"jsApi/Date/parse.md","filePath":"jsApi/Date/parse.md","lastUpdated":1791573371000}'),p={name:"jsApi/Date/parse.md"};function l(o,a,r,i,c,d){return e(),n("div",null,[...a[0]||(a[0]=[t(`<p><a href="https://developer.mozilla.org/zh-CN/docs/Web/JavaScript/Reference/Global_Objects/Date/parse" target="_blank">原文链接</a><a href="https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Date/parse" target="_blank">en</a></p><h1 id="date-parse" tabindex="-1">Date.parse() <a class="header-anchor" href="#date-parse" aria-label="Permalink to &quot;Date.parse()&quot;">​</a></h1><p>概要</p><p>Date.parse() 方法解析一个表示某个日期的字符串，并返回从1970-1-1 00:00:00 UTC 到该日期对象（该日期对象的UTC时间）的毫秒数， 如果该字符串无法识别，或者一些情况下，包含了不合法的日期数值（如：2015-02-31），则返回值为NaN。</p><p>不推荐在ES5之前使用Date.parse方法，因为字符串的解析完全取决于实现。直到至今，不同宿主在如何解析日期字符串上仍存在许多差异， 因此最好还是手动解析日期字符串（在需要适应不同格式时库能起到很大帮助）。</p><h2 id="语法" tabindex="-1">语法 <a class="header-anchor" href="#语法" aria-label="Permalink to &quot;语法&quot;">​</a></h2><p>显示调用：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(dateString)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>隐式调用：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(dateString)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><h3 id="参数" tabindex="-1">参数 <a class="header-anchor" href="#参数" aria-label="Permalink to &quot;参数&quot;">​</a></h3><ul><li><code>dateString</code> 一个符合 RFC2822 或 ISO 8601 日期格式的字符串（其他格式也许也支持，但结果可能与预期不符）</li></ul><h3 id="返回值" tabindex="-1">返回值 <a class="header-anchor" href="#返回值" aria-label="Permalink to &quot;返回值&quot;">​</a></h3><p>一个表示从1970-1-1 00:00:00 UTC到给定日期字符串所表示时间的毫秒数的数值。如果参数不能解析为一个有效的日期，则返回NaN。</p><h2 id="描述" tabindex="-1">描述 <a class="header-anchor" href="#描述" aria-label="Permalink to &quot;描述&quot;">​</a></h2><p>parse 方法接受一个日期字符串（例如 &quot;Dec 25, 1995&quot;），并返回从1970-1-1 00:00:00 UTC到该日期字符串所表示日期的毫秒数。该方 法在基于字符串值设置日期值时很有用，例如结合使用setTime() 方法和 Date() 构造函数。</p><p>parse 方法接受一个表示时间的字符串，返回相应的时间值。该方法可以接受符合 RFC2822 / IETF 日期语法 (RFC2822 Section 3.3) 的字符串，如 &quot;Mon, 25 Dec 1995 13:30:00 GMT&quot;。该方法能够理解美国大陆时区的缩写，但是为了更通用，应该使用时区偏移，如 &quot;Mon, 25 Dec 1995 13:30:00 +0430&quot; （格林威治的子午线向东偏移4小时30分钟）。如果没有指定时区，默认使用本地时区。</p><p>GMT 和 UTC 被看作相等。 如果 RFC2822 Section 3.3 格式中不包含时区信息时，会以本地时区来解析日期字符串。</p><p>由于在解析日期字符串时存在偏差会导致结果不一致，因此推荐始终手动解析日期字符串，特别是不同的ECMAScript实现会把诸如 “2015-10-12 12:00:00”的字符串解析为NaN，UTC或者本地时间。</p><h3 id="ecmascript-5-iso-8601-日期格式支持" tabindex="-1">ECMAScript 5 ISO-8601 日期格式支持 <a class="header-anchor" href="#ecmascript-5-iso-8601-日期格式支持" aria-label="Permalink to &quot;ECMAScript 5 ISO-8601 日期格式支持&quot;">​</a></h3><p>另外，日期时间字符串也可以使用 ISO 8601 格式。例如，&quot;2011-10-10&quot; （仅日期）或 &quot;2011-10-10T14:48:00&quot; （日期和时间）能够作 为参数被传递和解析。 如果参数字符串只包含日期格式，那么将会使用UTC时区来解析该参数。而如果是ISO 8601 格式中规定的时间加 日期的格式，则将会被作为本地时区处理。</p><p>虽然在日期字符串解析过程中会使用时区修饰符，但返回值总会是从由NaN表示的1970-1-1 00:00:00 UTC到该日期字符串所表示日期的毫秒数。</p><p>由于 parse() 是 Date 的一个静态方法 , 所以应该使用 Date.parse() 来调用，而不是作为 Date 的实例方法。</p><h3 id="默认时区的区别" tabindex="-1">默认时区的区别 <a class="header-anchor" href="#默认时区的区别" aria-label="Permalink to &quot;默认时区的区别&quot;">​</a></h3><p>当输入为 &quot;March 7, 2014&quot; 时， parse() 将默认使用本地时区。但如果使用 ISO 格式如 &quot;2014-03-07&quot; ，则会被默认为 UTC (ES5 和 ECMAScript 2015) 时区。 因此除非系统本地时区为 UTC，由这些字符串解析出的 Date 对象可能会因为 ECMAScript 版本不同而代表 不同的时间。这意味着两个看起来等效的字符串可能因为它们的格式不同而被转换成不同的值。</p><h3 id="引擎相关的日期格式" tabindex="-1">引擎相关的日期格式 <a class="header-anchor" href="#引擎相关的日期格式" aria-label="Permalink to &quot;引擎相关的日期格式&quot;">​</a></h3><p>ECMAScript 规范规定：如果一个字符串不符合标准格式，则函数可以使用任何由引擎决定的策略或解析算法。 Date.parse() 对于因 包含有无效元素而无法识别的 ISO 格式字符串或者日期应该返回 NaN 。</p><p>但是， 在如 ECMA-262 规范中定义的情况，如果因为无效值而导致日期字符串不能被识别为 ISO 格式时，根据浏览器和给定的值不同， 返回值可以是，也可以不是 NaN 。比如：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 包含无效值的非 ISO 格式字符串</span></span>
<span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;23/25/2014&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br></div></div><p>在 Firefox 30 中会被识别为本地时区的2015年12月25日，而在 Safari 7 中则是无效日期。但是，如果字符串被识别为 ISO 格式并且包 含无效值，则在所有遵循 ES5 或者更新标准的浏览器中都会返回 NaN 。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#6A737D;">// 包含无效值的 ISO 格式字符串</span></span>
<span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;2014-25-23&#39;</span><span style="color:#24292E;">).</span><span style="color:#6F42C1;">toISOString</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#6A737D;">// 在所有遵循 ES5的浏览器中返回 &quot;RangeError: invalid date&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br></div></div><p>SpiderMonkey 的引擎策略可以在 jsdate.cpp 中找到。字符串 &quot;10 06 2014&quot; 可以作为非 ISO 格式字符串使用自定义处理方式的例子。 参见这篇关于解析如何进行的粗略纲要。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;10 06 2014&#39;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>将会被解析为本地时间 2014年10月6日，而不是6月10日。另一个例子</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#D73A49;">new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo-bar 2014&#39;</span><span style="color:#24292E;">).</span><span style="color:#6F42C1;">toString</span><span style="color:#24292E;">();</span></span>
<span class="line"><span style="color:#6A737D;">// 返回: &quot;Invalid Date&quot;</span></span>
<span class="line"></span>
<span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;foo-bar 2014&#39;</span><span style="color:#24292E;">);</span></span>
<span class="line"><span style="color:#6A737D;">// 返回: NaN</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="例子" tabindex="-1">例子 <a class="header-anchor" href="#例子" aria-label="Permalink to &quot;例子&quot;">​</a></h2><p>使用 Date.parse()</p><p>如果 IPOdate 是一个已经存在的 Date 对象，则可以把其设置为本地时间 1995年8月9日。如下：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">IPOdate.</span><span style="color:#6F42C1;">setTime</span><span style="color:#24292E;">(Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&#39;Aug 9, 1995&#39;</span><span style="color:#24292E;">));</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>其他一些解析非标准格式日期的例子：</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Aug 9, 1995&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在时区 GMT-0300 中返回 807937200000 ，在其他时区中返回另外的值，因为未指定时区并且不是 ISO 格式，所以默认使用本地时区。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Wed, 09 Aug 1995 00:00:00 GMT&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因为指定了时区 GMT (UTC)，所以不管本地时区如何，总是返回 807926400000 。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Wed, 09 Aug 1995 00:00:00&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在时区 GMT-0300 中返回 807937200000 ，在其他时区中返回另外的值，因为没有时区标志并且不是 ISO 格式，所以作为本地时区处理。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Thu, 01 Jan 1970 00:00:00 GMT&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因为指定了时区 GMT (UTC)，所以不管本地时区如何，总是返回 0 。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Thu, 01 Jan 1970 00:00:00&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>在时区 GMT-0400 中返回 14400000，在其他时区中返回另外的值，因为未指定时区并且不是 ISO 格式，所以使用本地时区处理。</p><div class="language-javascript line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">javascript</span><pre class="shiki github-light vp-code" tabindex="0"><code><span class="line"><span style="color:#24292E;">Date.</span><span style="color:#6F42C1;">parse</span><span style="color:#24292E;">(</span><span style="color:#032F62;">&quot;Thu, 01 Jan 1970 00:00:00 GMT-0400&quot;</span><span style="color:#24292E;">);</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><p>因为指定了时区 GMT (UTC)，所以不管本地时区如何，总是返回 14400000</p><h2 id="规范" tabindex="-1">规范 <a class="header-anchor" href="#规范" aria-label="Permalink to &quot;规范&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:left;">Specification</th><th style="text-align:left;">Status</th><th style="text-align:left;">Comment</th></tr></thead><tbody><tr><td style="text-align:left;">ECMAScript 1rd Edition (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;">Initial definition</td></tr><tr><td style="text-align:left;">ECMAScript 5.1 (ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr><tr><td style="text-align:left;">ECMAScript 2015 (6th Edition, ECMA-262)</td><td style="text-align:left;">Standard</td><td style="text-align:left;"></td></tr></tbody></table><div class="danger custom-block"><p class="custom-block-title">警告</p><p>Safari浏览器不兼容 &quot;2016-01-01&quot;的写法,请使用 &quot;2016/01/01&quot;</p></div>`,55)])])}const h=s(p,[["render",l]]);export{b as __pageData,h as default};
